            const line = await handle.readFile("utf8");
            if (!line.endsWith("\n")) throw new Error(`incomplete tshark completion file: ${name}`);
            const record = parseTsharkCompletion(JSON.parse(line));
            if (`tshark-${record.identity}.ndjson` !== name) throw new Error(`tshark completion identity mismatch: ${name}`);
