          } finally { await handle.close(); }
        } catch (cause: any) { error ??= String(cause); }
      }
    } catch (cause: any) {
      if (cause?.code !== "ENOENT") error = String(cause);
    }
    return { records, error, acknowledge: async () => {
      for (const file of files) {
        const stat = await fs.lstat(file.filename).catch(cause => { if (cause?.code !== "ENOENT") throw cause; return null; });
        if (stat?.isFile() && !stat.isSymbolicLink() && stat.dev === file.dev && stat.ino === file.ino) await fs.unlink(file.filename);
      }
    } };
  }
